using System;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
namespace ParoleRP {
 public sealed partial class Desktop {
  UsageTracker usage;readonly ConnectionHealth health=new ConnectionHealth();int usagePeriod;Action refreshUsage,refreshHealth,refreshUsageClock;System.Windows.Threading.DispatcherTimer usageClock;
  void StartUsageClock(){usageClock=new System.Windows.Threading.DispatcherTimer{Interval=TimeSpan.FromSeconds(1)};usageClock.Tick+=(s,e)=>{if(!w.IsVisible)return;if(refreshHealth!=null)refreshHealth();if(refreshUsageClock!=null)refreshUsageClock();};usageClock.Start();}
  void ReceiveReport(ApiReport report){usage.Record(report,DateTime.Now);health.Record(report,DateTime.UtcNow);if(refreshUsage!=null)refreshUsage();if(refreshHealth!=null)refreshHealth();}
  void UsagePage(){Title("Consommation","Vos demandes et les jetons annoncés par Groq.");var period=new ComboBox{ItemsSource=new[]{"Cette session","Aujourd’hui","Ce mois"},SelectedIndex=usagePeriod,Width=180,HorizontalAlignment=HorizontalAlignment.Left};var values=new StackPanel();Action update=()=>{values.Children.Clear();var total=usage.Period(usagePeriod,DateTime.Now);values.Children.Add(Three(UsageValue("Correction",total.Corrections,total.CorrectionTokens,total.MeasuredCorrections),UsageValue("Reformulation",total.Rephrases,total.RephraseTokens,total.MeasuredRephrases),UsageValue("Génération",total.Generations,total.GenerationTokens,total.MeasuredGenerations)));values.Children.Add(Space(25));values.Children.Add(Three(UsageValue("Jetons d’entrée",total.Input),UsageValue("Jetons de sortie",total.Output),UsageValue("Dont entrée en cache",total.Cached)));values.Children.Add(Space(20));values.Children.Add(T(total.Requests+" demandes · "+total.Failures+" échecs · "+total.Tests+" tests API",12,"#989892"));if(total.Unreported>0)values.Children.Add(T(total.Unreported+" demande(s) sans mesure de jetons.",12,"#D4AF78"));};refreshUsage=update;period.SelectionChanged+=(s,e)=>{usagePeriod=period.SelectedIndex;update();};update();
   var detail=new Expander{Header="Comprendre les chiffres",Margin=new Thickness(0,12,0,0),Foreground=B("#989892"),Content=S(Space(12),T("Les demandes incluent les essais et les réponses inchangées. Les jetons comprennent les préparations de contexte et les réponses mesurées, même si le remplacement est refusé. Certains échecs ne fournissent aucune mesure. Ces chiffres ne représentent pas le quota restant chez Groq.",12,"#989892"),Space(8),T("Historique local agrégé sur 400 jours. Aucun texte, profil ou clé API n’y est enregistré.",12,"#989892"))};
   host.Children.Add(Card(S(period,Space(25),values,detail)));var sessionLabel=T("",12,"#989892");refreshUsageClock=()=>{var elapsed=DateTime.Now-usage.Started;sessionLabel.Text="Session : "+((int)elapsed.TotalHours).ToString("00")+":"+elapsed.Minutes.ToString("00")+" · "+(usage.Session.Requests/Math.Max(1.0,elapsed.TotalMinutes)).ToString("0.0")+" demandes/min";};refreshUsageClock();host.Children.Add(Row(sessionLabel,SmallButton("Nouvelle session",()=>{if(busy||capturing){Note("Attendez la fin de la demande en cours.");return;}usage.Reset();update();Render();})));if(usage.Warning!=null)host.Children.Add(T(usage.Warning,12,"#D4AF78"));
  }
  UIElement Three(params UIElement[] items){var grid=new Grid();for(int i=0;i<items.Length;i++){if(i>0)grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(20)});grid.ColumnDefinitions.Add(new ColumnDefinition());Grid.SetColumn(items[i],i*2);grid.Children.Add(items[i]);}return grid;}
  UIElement UsageValue(string label,long value,long tokens=0,long measured=0){var block=S(T(label,12,"#989892"),Space(8),T(value.ToString("N0"),28));if(measured>0){var average=T("≈ "+Math.Round((double)tokens/measured).ToString("N0")+" jetons / demande",11,"#989892");average.ToolTip="Moyenne des demandes mesurées, hors jetons d’entrée en cache.";block.Children.Add(average);}return block;}
 }
}
